import React, { useState } from 'react';

const TaskForm = ({ addTask }) => {
  const [task, setTask] = useState({ title: '', description: '', quadrant: '' });

  const handleSubmit = (e) => {
    e.preventDefault();
    addTask(task);
    setTask({ title: '', description: '', quadrant: '' });
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="text"
        placeholder="Title"
        value={task.title}
        onChange={(e) => setTask({ ...task, title: e.target.value })}
      />
      <input
        type="text"
        placeholder="Description"
        value={task.description}
        onChange={(e) => setTask({ ...task, description: e.target.value })}
      />
      <select
        value={task.quadrant}
        onChange={(e) => setTask({ ...task, quadrant: e.target.value })}
      >
        <option value="">Select Quadrant</option>
        <option value="Urgent-Important">Urgent & Important</option>
        <option value="NotUrgent-Important">Not Urgent & Important</option>
        <option value="Urgent-NotImportant">Urgent & Not Important</option>
        <option value="NotUrgent-NotImportant">Not Urgent & Not Important</option>
      </select>
      <button type="submit">Add Task</button>
    </form>
  );
};

export default TaskForm;
